<script>
    function toggleBookmark(btn) {
      const icon = btn.querySelector('.material-symbols-outlined');
      const text = btn.querySelector('.bookmark-text');
      const isSaved = icon.innerText.trim() === 'bookmark';
      
      if (isSaved) {
        icon.innerText = 'bookmark_border';
        icon.style.fontVariationSettings = "'FILL' 0";
        if (text) text.innerText = 'Simpan Bacaan';
      } else {
        icon.innerText = 'bookmark';
        icon.style.fontVariationSettings = "'FILL' 1";
        if (text) text.innerText = 'Koleksi';
      }
    }

    function toggleItemBookmark(btn) {
      const icon = btn.querySelector('.material-symbols-outlined');
      const isSaved = icon.innerText.trim() === 'bookmark';
      
      if (isSaved) {
        icon.innerText = 'bookmark_border';
        icon.style.fontVariationSettings = "'FILL' 0";
        icon.classList.remove('text-primary');
      } else {
        icon.innerText = 'bookmark';
        icon.style.fontVariationSettings = "'FILL' 1";
        icon.classList.add('text-primary');
      }
    }

    // Filter Chips interactive state
    const chips = document.querySelectorAll('.category-chip');
    chips.forEach(chip => {
      chip.addEventListener('click', () => {
        chips.forEach(c => {
          c.className = "px-5 py-2 rounded-full font-label-md text-label-md bg-surface-container-lowest text-on-surface-variant hover:bg-surface-container hover:text-on-surface shadow-sm transition-all category-chip";
        });
        chip.className = "px-5 py-2 rounded-full font-label-md text-label-md bg-primary-container text-on-primary shadow-sm hover:opacity-95 transition-all category-chip";
      });
    });
  </script>
